import{_ as n,o as s,c as h,a3 as a,j as e,a as u}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/suchen-gruppenprozesse/gp-schulbesuchsjahre-berechnen.jpg",l="/bilder/suchen-gruppenprozesse/eintrag-schulbesuchsjahre.jpg",t="/bilder/suchen-gruppenprozesse/einschulungsjahr.jpg",c="/bilder/suchen-gruppenprozesse/ep-jahre.jpg",_=JSON.parse('{"title":"Schulbesuchsjahre neu berechnen","description":"","frontmatter":{"title":"Schulbesuchsjahre neu berechnen","source_pageid":386,"source_revision":5330},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/schulbesuchsjahre-neu-berechnen-gruppenprozesse-allgemein.md","filePath":"schild3/suchen-gruppenprozesse/schulbesuchsjahre-neu-berechnen-gruppenprozesse-allgemein.md"}'),p={name:"schild3/suchen-gruppenprozesse/schulbesuchsjahre-neu-berechnen-gruppenprozesse-allgemein.md"};function d(o,r,g,b,m,j){return s(),h("div",null,[...r[0]||(r[0]=[a('<h1 id="schulbesuchsjahre-neu-berechnen" tabindex="-1">Schulbesuchsjahre neu berechnen <a class="header-anchor" href="#schulbesuchsjahre-neu-berechnen" aria-label="Permalink to &quot;Schulbesuchsjahre neu berechnen&quot;">​</a></h1><p>Kontrollieren Sie die Schulbesuchsjahre anhand der gespeicherten Laufbahndaten. An Grundschulen und Schulen der Sekundarstufe I ist die Anzeige nicht manuell editierbar.</p><p><a href="/bilder/suchen-gruppenprozesse/gp-schulbesuchsjahre-berechnen.jpg"><img src="'+i+'" alt="Gruppenprozess Schulbesuchsjahre neu berechnen." loading="lazy"></a></p><p><em>Gruppenprozess Schulbesuchsjahre neu berechnen.</em></p><p>Dieser Gruppenprozess aus der Kategorie <em>Allgemeines</em> berechnet anhand des eingetragenen Einschulungsjahres die Anzahl der Schulbesuchsjahre.</p><p><a href="/bilder/suchen-gruppenprozesse/eintrag-schulbesuchsjahre.jpg"><img src="'+l+'" alt="Schulbesuchsjahre" loading="lazy"></a></p><p><em>Schulbesuchsjahre</em></p><p>Die neu berechneten Schulbesuchsjahre werden auf der Registerkarte <em>Schüler ➜ Individualdaten I</em> eingetragen - dieses gilt nur für Schülerinnen und Schüler mit dem Status &quot;Aktiv&quot; oder &quot;Extern&quot;.</p><p><a href="/bilder/suchen-gruppenprozesse/einschulungsjahr.jpg"><img src="'+t+'" alt="Einschulungsjahr" loading="lazy"></a></p><p><em>Einschulungsjahr</em></p><p>Das Einschulungsjahr befindet sich auf der Karteikarte <em>Schüler ➜ Individualdaten II</em>.</p><p>An <strong>Grundschulen und Schulen der Sekundarstufe I</strong> wird das laufende Schulbesuchsjahr aus den vorhandenen Daten berechnet und <strong>kann nicht manuell bearbeitet werden</strong>. Korrigieren Sie deshalb die zugrunde liegenden Angaben, insbesondere das Einschulungsjahr und die EP-Daten.</p><p>Soweit der Gruppenprozess in Ihrer Schulform angeboten wird, kontrollieren Sie nach der Neuberechnung das Ergebnis anhand der tatsächlichen Laufbahn.</p><p><a href="/bilder/suchen-gruppenprozesse/ep-jahre.jpg"><img src="'+c+'" alt="Anzahl EP-Jahre" loading="lazy"></a></p><p><em>Anzahl EP-Jahre</em></p><p>Das folgende Bild zeigt einen früheren Programmstand; die aktuelle Eingabestelle ist im verlinkten EP-Artikel beschrieben.</p><p>Eine Besonderheit ergibt sich bei Kindern, die drei Jahre in der Schuleingangsphase (EP) der Grundschule verbracht haben.</p><p>Jahrgänge und EP-Jahre sind getrennt: Die laufende Zuordnung von <strong>E1, E2 oder E3</strong> erfolgt in Jahrgang 01 und 02 in jedem Halbjahr. Der gespeicherte Wert wird in <strong>Individualdaten I</strong> angezeigt und ist dort ab Jahrgang 03 korrigierbar. Siehe <a href="/schild3/schueler/eintragung-der-ep-jahre-tutorial.html">EP-Jahre</a>.</p><p>Das dritte EP-Jahr wird aber bei der Berechnung der Erfüllung der Vollzeitschulpflicht nicht mitgezählt.</p><p><strong>Videotutorial</strong></p>',20),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/2DQO0IbGqXc?",frameborder:"0",allowfullscreen:""},null,-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Schulbesuchsjahre_neu_berechnen_(Gruppenprozesse_Allgemein)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),u(" · Quellrevision 5330.")],-1)])])}const S=n(p,[["render",d]]);export{_ as __pageData,S as default};
